// Des: Run a list of page steps at human pace with halt checks
// Flo: pause flag > pace delay > find by role + label (retry) > scroll > click or type > halt check > next step
// I/O: Steps + Run (page, rng, conf, state) > page effects; errors Halted NeedLogin NoElement Drift Paused
// ===================================================================
const std = @import("std"); const pg = @import("ru-page-snap.zig"); const inpu = @import("ru-huma-inpu.zig"); const pace = @import("ru-huma-pace.zig"); const halt = @import("ru-safe-halt.zig"); const stat = @import("st-stat-main.zig"); const fld = @import("ut-text-fold.zig");
const CF = .{ .retr_nap = 400, .expe_dflt = 6000, .flag_paus = "pause" };
pub const Op = enum { goto, click, typez, key, wait, expect, scroll, upload };
pub const Step = struct { op: Op, role: []const u8 = "", labs: []const []const u8 = &.{}, text: []const u8 = "", nth: usize = 0, ms: u32 = 0, commit: bool = false };
pub const Run = struct { env: inpu.Env, store: ?*stat.Stat, base: []const u8, done: u32 = 0, crossed: bool = false, hltk: ?halt.Halt = null };
fn secs(run: *Run, cnt: u32) void { _ = cnt; const lo = @as(u64, run.env.conf.acti_dely_secs[0]) * 1000; const hi = @as(u64, run.env.conf.acti_dely_secs[1]) * 1000; pace.nap(run.env.page.iozz, pace.logn(run.env.rng, lo, hi), run.env.conf.time_scal_perc); }
fn armz(run: *Run) void { run.env.page.arm(run.env.conf.brow_time_seco * 1000); }
pub fn haltCheck(run: *Run) !void { const aren = run.env.aren; const urlz = run.env.page.urlNow(aren) catch return; const txt = run.env.page.textNow(aren) catch ""; if (halt.check(urlz, txt)) |kind| { run.hltk = kind; if (halt.isLogout(kind)) return error.NeedLogin; return error.Halted; } }
fn pauseChk(run: *Run) !void { if (run.store) |sto| { if (sto.flagGet(CF.flag_paus) catch false) return error.Paused; } }
fn findRetry(run: *Run, role: []const u8, labs: []const []const u8, nth: usize) !i64 { var att: u32 = 0; while (att < run.env.conf.retr_coun_maxz) : (att += 1) { armz(run); if (try run.env.page.axFind(run.env.aren, role, labs, nth)) |bid| return bid; try haltCheck(run); pace.nap(run.env.page.iozz, @as(u64, CF.retr_nap) * (att + 1), run.env.conf.time_scal_perc); } return error.NoElement; }
fn clickEl(run: *Run, role: []const u8, labs: []const []const u8, nth: usize) !void { const bid = try findRetry(run, role, labs, nth); armz(run); try run.env.page.scrollInto(run.env.aren, bid); const pnt = try run.env.page.center(run.env.aren, bid); try inpu.click(&run.env, pnt.x, pnt.y); }
fn uploadFile(run: *Run, path: []const u8) !void { const aren = run.env.aren; armz(run); const doc = try run.env.page.call(aren, "DOM.getDocument", "{\"depth\":0}"); const rid = doc.object.get("root").?.object.get("nodeId").?.integer; const qp = try std.json.Stringify.valueAlloc(aren, .{ .nodeId = rid, .selector = "input[type=file]" }, .{}); const qr = try run.env.page.call(aren, "DOM.querySelector", qp); const nid = (qr.object.get("nodeId") orelse return error.NoElement).integer; if (nid == 0) return error.NoElement; const sp = try std.json.Stringify.valueAlloc(aren, .{ .nodeId = nid, .files = [_][]const u8{path} }, .{}); _ = try run.env.page.call(aren, "DOM.setFileInputFiles", sp); }
fn expectTxt(run: *Run, stp: Step) !void { const tot: u32 = if (stp.ms == 0) CF.expe_dflt else stp.ms; var wtd: u32 = 0; while (true) { armz(run); const txt = run.env.page.textNow(run.env.aren) catch ""; if (try fld.matchAny(run.env.aren, txt, stp.labs)) return; try haltCheck(run); if (wtd >= tot) return error.Drift; pace.nap(run.env.page.iozz, 250, run.env.conf.time_scal_perc); wtd += 250; } }
pub fn runSteps(run: *Run, steps: []const Step) !void { for (steps) |stp| { try pauseChk(run); if (stp.commit) run.crossed = true; switch (stp.op) { .goto => { secs(run, 0); armz(run); const urlz = if (std.mem.startsWith(u8, stp.text, "http")) stp.text else try std.fmt.allocPrint(run.env.aren, "{s}{s}", .{ run.base, stp.text }); try run.env.page.navigate(run.env.aren, urlz); try haltCheck(run); }, .click => { secs(run, 0); try clickEl(run, if (stp.role.len > 0) stp.role else "button", stp.labs, stp.nth); try haltCheck(run); }, .typez => { secs(run, 0); try clickEl(run, if (stp.role.len > 0) stp.role else "textbox", stp.labs, stp.nth); armz(run); try inpu.typeText(&run.env, stp.text); }, .key => { armz(run); try inpu.pressKey(&run.env, stp.text); run.env.page.nap(150); try haltCheck(run); }, .wait => pace.nap(run.env.page.iozz, stp.ms, run.env.conf.time_scal_perc), .expect => try expectTxt(run, stp), .scroll => { armz(run); try inpu.scrollBy(&run.env, @floatFromInt(stp.ms)); }, .upload => try uploadFile(run, stp.text) } run.done += 1; } }
